describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against the original subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200),
        ],
        "sum",
      );
      // sum mode: each sees original 1000 → 100 + 200 = 300
      expect(sut.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for non-positive subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
      expect(sut.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const sut = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0, plus 100 = 100
      expect(sut.computeDiscountCents(500)).toBe(100);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const sut = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(sut.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("chains discounts: each policy sees remaining after prior discounts", () => {
      const sut = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90 → remaining 810
        ],
        "chain",
      );
      // total discount = 100 + 90 = 190
      expect(sut.computeDiscountCents(1000)).toBe(190);
    });

    it("stops reducing when remaining hits 0", () => {
      const sut = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800),
          new FixedAmountDiscountPolicy(300), // only 200 left
        ],
        "chain",
      );
      // 800 + min(300, 200) = 800 + 200 = 1000
      expect(sut.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
      const p10 = new PercentageDiscountPolicy(10);
      const f200 = new FixedAmountDiscountPolicy(200);

      const percentFirst = new CompositeDiscountPolicy([p10, f200], "chain");
      const fixedFirst = new CompositeDiscountPolicy([f200, p10], "chain");

      // percent first: 10% of 1000=100, then min(200,900)=200 → total 300
      expect(percentFirst.computeDiscountCents(1000)).toBe(300);
      // fixed first: min(200,1000)=200, then 10% of 800=80 → total 280
      expect(fixedFirst.computeDiscountCents(1000)).toBe(280);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 in chain mode", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const sut = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // negative clamped to 0 → remaining still 500, then 100
      expect(sut.computeDiscountCents(500)).toBe(100);
    });
  });
});

