import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

const emptyLines: CartLine[] = [];

describe("FreeShippingCalculator", () => {
  const sut = new FreeShippingCalculator();

  it("always returns 0", () => {
    expect(sut.computeShippingCents([], 0)).toBe(0);
    expect(sut.computeShippingCents([makeLine("a", 500)], 5000)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents and zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(0, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty lines", () => {
      const sut = new FlatShippingCalculator(500);
      expect(sut.computeShippingCents(emptyLines, 1000)).toBe(0);
    });

    it("returns flatCents for non-empty cart without threshold", () => {
      const sut = new FlatShippingCalculator(500);
      expect(sut.computeShippingCents([makeLine("a", 100)], 1000)).toBe(500);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const sut = new FlatShippingCalculator(500, 5000);
      expect(sut.computeShippingCents([makeLine("a", 100)], 5000)).toBe(0);
      expect(sut.computeShippingCents([makeLine("a", 100)], 6000)).toBe(0);
    });

    it("returns flatCents when subtotal is below freeOver threshold", () => {
      const sut = new FlatShippingCalculator(500, 5000);
      expect(sut.computeShippingCents([makeLine("a", 100)], 4999)).toBe(500);
    });

    it("returns 0 flatCents when freeOverCents is undefined and subtotal is large", () => {
      const sut = new FlatShippingCalculator(0);
      expect(sut.computeShippingCents([makeLine("a", 100)], 99999)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const sut = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1500 },
      ],
      2500,
    );

    it("returns 0 for empty lines", () => {
      expect(sut.computeShippingCents(emptyLines, 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
      ];
      expect(sut.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects the first bracket whose upToGrams >= weight", () => {
      // 200g → first bracket (500g, 300¢)
      expect(sut.computeShippingCents([makeLine("a", 200)], 1000)).toBe(300);
      // exactly 500g → first bracket boundary
      expect(sut.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
      // 501g → second bracket (2000g, 700¢)
      expect(sut.computeShippingCents([makeLine("a", 501)], 1000)).toBe(700);
      // exactly 2000g → second bracket boundary
      expect(sut.computeShippingCents([makeLine("a", 2000)], 1000)).toBe(700);
      // 2001g → third bracket (5000g, 1500¢)
      expect(sut.computeShippingCents([makeLine("a", 2001)], 1000)).toBe(1500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 6000g > 5000g → overflow = 2500¢
      expect(sut.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(2500);
    });

    it("uses last bracket cost when no overflow is set", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      // 3000g > 2000g → fallback to last bracket cost = 700
      expect(
        noOverflow.computeShippingCents([makeLine("a", 3000)], 1000),
      ).toBe(700);
    });

    it("sorts brackets correctly regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g should match first bracket (500g) after sort
      expect(
        unordered.computeShippingCents([makeLine("a", 400)], 1000),
      ).toBe(300);
    });

    it("sums weight across multiple lines with quantity", () => {
      // 2 * 300g + 1 * 200g = 800g → second bracket (2000g, 700¢)
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)];
      expect(sut.computeShippingCents(lines, 1000)).toBe(700);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("exposes productId, requested, and available properties", () => {
    const err = new InventoryError("out of stock", "p1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("p1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("supports undefined available", () => {
    const err = new InventoryError("gone", "p2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    {
      product: { id: "a", name: "Widget", unitPriceCents: 100 },
      quantity: 2,
    },
    {
      product: { id: "b", name: "Gadget", unitPriceCents: 200 },
      quantity: 1,
    },
  ];

  it("updates unitPriceCents from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(lines, fetcher);

    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(250);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves product properties other than unitPriceCents", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const result = await refreshPrices(
      [
        {
          product: {
            id: "x",
            name: "Heavy",
            unitPriceCents: 100,
            weightGrams: 500,
            currency: "EUR",
          },
          quantity: 1,
        },
      ],
      fetcher,
    );
    expect(result[0]!.product.name).toBe("Heavy");
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.unitPriceCents).toBe(999);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("network");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = {
  id: "b",
  name: "Gadget",
  unitPriceCents: 2000,
  weightGrams: 500,
};

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding the same product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("tracks separate products independently", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      expect(cart.itemCount).toBe(3);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
      expect(() => cart.add(bad, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("returns true and removes an existing product", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for existing product", () => {
      const cart = new Cart();
      cart.add(productA, 5);
      cart.updateQuantity("a", 3);
      expect(cart.itemCount).toBe(3);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 5);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for product not in cart", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("x", 1)).toThrow("not in the cart");
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);
      // mutating snapshot should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals — pricing pipeline", () => {
    it("uses default seams (no discount, no tax, free shipping)", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2 * 1000 = 2000
      const t = cart.totals();
      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(2000);
    });

    it("computes tax on the discounted subtotal (not raw subtotal)", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn((taxable: number) =>
          Math.floor(taxable * 0.1),
        ),
      };
      const cart = new Cart({ discountPolicy, taxCalculator });
      cart.add(productA, 2); // subtotal = 2000, discount = 500, discounted = 1500
      const t = cart.totals();
      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(500);
      // tax on 1500 at 10% = 150
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1500, "US");
      expect(t.taxCents).toBe(150);
    });

    it("clamps discount to [0, subtotal]", () => {
      // discount returning more than subtotal
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 1); // subtotal = 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(1000);
      expect(t.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => -100,
      };
      const cart = new Cart({ taxCalculator });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("passes the discounted subtotal to shipping calculator", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 300,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn(() => 500),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(productA, 1); // subtotal = 1000, discounted = 700
      cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        700,
      );
    });

    it("computes total = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => 80,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
      });
      cart.add(productA, 1); // subtotal=1000, discount=200, discounted=800
      const t = cart.totals();
      // total = 800 + 80 + 500 = 1380
      expect(t.totalCents).toBe(1380);
    });

    it("uses configured region for tax", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn(() => 0),
      };
      const cart = new Cart({ taxCalculator, region: "FR" });
      cart.add(productA, 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("returns zeroed totals for an empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without any collaborators", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(productA, 2); // original price 1000
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      // 2 * 1500 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("throws InventoryError when item is not available", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(2);
        expect(ie.message).toBe("low stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3, // less than requested 10
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(3);
      }
    });

    it("passes when inventory is sufficient", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("uses asyncTaxProvider for async tax computation", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({
        discountPolicy,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(productA, 1); // subtotal = 1000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // discounted = 1000 - 200 = 800, tax = floor(800 * 0.1) = 80
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(800 + 80 + 500);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price error")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price error",
      );
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("generates default message when no reason is provided", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.message).toContain("insufficient stock");
        expect(ie.available).toBe(0);
      }
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 1);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1200) // a → 1200
          .mockResolvedValueOnce(2500), // b → 2500
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal = 1200 + 2500 = 3700
      expect(result.totals.subtotalCents).toBe(3700);
      // discount = 100, discounted = 3600
      expect(result.totals.discountCents).toBe(100);
      // tax = floor(3600 * 0.05) = 180
      expect(result.totals.taxCents).toBe(180);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("checks inventory after price refresh", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const callOrder: string[] = [];

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation(async () => {
          callOrder.push("fetch");
          return 1000;
        }),
      };
