      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(2000);
    });

    it("computes tax on the discounted subtotal (not raw subtotal)", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn((taxable: number) =>
          Math.floor(taxable * 0.1),
        ),
      };
      const cart = new Cart({ discountPolicy, taxCalculator });
      cart.add(productA, 2); // subtotal = 2000, discount = 500, discounted = 1500
      const t = cart.totals();
      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(500);
      // tax on 1500 at 10% = 150
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1500, "US");
      expect(t.taxCents).toBe(150);
    });

    it("clamps discount to [0, subtotal]", () => {
      // discount returning more than subtotal
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 1); // subtotal = 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(1000);
      expect(t.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => -100,
      };
      const cart = new Cart({ taxCalculator });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("passes the discounted subtotal to shipping calculator", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 300,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn(() => 500),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(productA, 1); // subtotal = 1000, discounted = 700
      cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        700,
      );
    });

    it("computes total = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => 80,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
      });
      cart.add(productA, 1); // subtotal=1000, discount=200, discounted=800
      const t = cart.totals();
      // total = 800 + 80 + 500 = 1380
      expect(t.totalCents).toBe(1380);
    });

    it("uses configured region for tax", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn(() => 0),
      };
      const cart = new Cart({ taxCalculator, region: "FR" });
      cart.add(productA, 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("returns zeroed totals for an empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without any collaborators", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(productA, 2); // original price 1000
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      // 2 * 1500 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("throws InventoryError when item is not available", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(2);
        expect(ie.message).toBe("low stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3, // less than requested 10
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(3);
      }
    });

    it("passes when inventory is sufficient", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("uses asyncTaxProvider for async tax computation", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({
        discountPolicy,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(productA, 1); // subtotal = 1000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // discounted = 1000 - 200 = 800, tax = floor(800 * 0.1) = 80
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(800 + 80 + 500);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price error")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price error",
      );
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("generates default message when no reason is provided", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.message).toContain("insufficient stock");
        expect(ie.available).toBe(0);
      }
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 1);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1200) // a → 1200
          .mockResolvedValueOnce(2500), // b → 2500
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal = 1200 + 2500 = 3700
      expect(result.totals.subtotalCents).toBe(3700);
      // discount = 100, discounted = 3600
      expect(result.totals.discountCents).toBe(100);
      // tax = floor(3600 * 0.05) = 180
      expect(result.totals.taxCents).toBe(180);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("checks inventory after price refresh", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const callOrder: string[] = [];

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation(async () => {
          callOrder.push("fetch");
          return 1000;
        }),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockImplementation(async () => {
          callOrder.push("check");
          return { available: true };
        }),
      };

      await cart.checkout({ priceFetcher, inventoryChecker });
      expect(callOrder).toEqual(["fetch", "check"]);
    });
  });
});
