import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const sut = new NoTaxCalculator();

  it.each([
    [1000, "US", 0],
    [0, "FR", 0],
    [-500, "DE", 0],
  ])("computeTaxCents(%i, %s) returns %i", (taxable, region, expected) => {
    expect(sut.computeTaxCents(taxable, region)).toBe(expected);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects out-of-range defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
      expect(() => new RegionalTaxCalculator({}, Infinity)).toThrow(RangeError);
    });

    it("rejects out-of-range per-region rates", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": -0.01 }),
      ).toThrow(RangeError);
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
      expect(
        () => new RegionalTaxCalculator({ "US-CA": NaN }),
      ).toThrow(RangeError);
    });

    it("accepts valid rates at boundaries", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 0, "FR": 1 }, 0.5),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const sut = new RegionalTaxCalculator(
      { "US-CA": 0.0875, "FR": 0.20, "JP": 0.10 },
      0.05,
    );

    it.each([
      [1000, "US-CA", 87],   // 1000 * 0.0875 = 87.5 → 87
      [1000, "FR", 200],     // 1000 * 0.20 = 200
      [1000, "JP", 100],     // 1000 * 0.10 = 100
      [1000, "DE", 50],      // fallback to default 0.05 → 50
      [0, "US-CA", 0],       // zero taxable
      [-100, "US-CA", 0],    // negative taxable
    ])(
      "computeTaxCents(%i, %s) = %i",
      (taxable, region, expected) => {
        expect(sut.computeTaxCents(taxable, region)).toBe(expected);
      },
    );

    it("rounds down fractional tax", () => {
      // 999 * 0.0875 = 87.4125 → 87
      expect(sut.computeTaxCents(999, "US-CA")).toBe(87);
    });

    it("uses 0 when no default rate and unknown region", () => {
      const calc = new RegionalTaxCalculator({ "US": 0.1 });
      expect(calc.computeTaxCents(1000, "XX")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for non-positive taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.1,
    };
    const sut = new AsyncTaxCalculator(provider);
    expect(await sut.computeTaxCents(0, "US")).toBe(0);
    expect(await sut.computeTaxCents(-100, "US")).toBe(0);
  });

  it("computes tax using the async rate and floors result", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.0875,
    };
    const sut = new AsyncTaxCalculator(provider);
    // 1000 * 0.0875 = 87.5 → 87
    expect(await sut.computeTaxCents(1000, "US-CA")).toBe(87);
  });

  it("throws RangeError for invalid rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 1.5,
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => -0.1,
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => NaN,
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => {
        throw new Error("network failure");
      },
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(
      "network failure",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty array", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      {
        product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 },
        quantity: 2,
      },
      {
        product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 },
        quantity: 3,
      },
    ];
    // (500*2) + (300*3) = 1000 + 900 = 1900
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      {
        product: { id: "a", name: "A", unitPriceCents: 100 },
        quantity: 5,
      },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

