+      [
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 2000, costCents: 700 },
+        { upToGrams: 5000, costCents: 1500 },
+      ],
+      2500,
+    );
+
+    it("returns 0 for empty lines", () => {
+      expect(sut.computeShippingCents(emptyLines, 1000)).toBe(0);
+    });
+
+    it("returns 0 when total weight is 0", () => {
+      const lines: CartLine[] = [
+        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
+      ];
+      expect(sut.computeShippingCents(lines, 1000)).toBe(0);
+    });
+
+    it("selects the first bracket whose upToGrams >= weight", () => {
+      // 200g → first bracket (500g, 300¢)
+      expect(sut.computeShippingCents([makeLine("a", 200)], 1000)).toBe(300);
+      // exactly 500g → first bracket boundary
+      expect(sut.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
+      // 501g → second bracket (2000g, 700¢)
+      expect(sut.computeShippingCents([makeLine("a", 501)], 1000)).toBe(700);
+      // exactly 2000g → second bracket boundary
+      expect(sut.computeShippingCents([makeLine("a", 2000)], 1000)).toBe(700);
+      // 2001g → third bracket (5000g, 1500¢)
+      expect(sut.computeShippingCents([makeLine("a", 2001)], 1000)).toBe(1500);
+    });
+
+    it("uses overflow cost when weight exceeds all brackets", () => {
+      // 6000g > 5000g → overflow = 2500¢
+      expect(sut.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(2500);
+    });
+
+    it("uses last bracket cost when no overflow is set", () => {
+      const noOverflow = new WeightBasedShippingCalculator([
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 2000, costCents: 700 },
+      ]);
+      // 3000g > 2000g → fallback to last bracket cost = 700
+      expect(
+        noOverflow.computeShippingCents([makeLine("a", 3000)], 1000),
+      ).toBe(700);
+    });
+
+    it("sorts brackets correctly regardless of input order", () => {
+      const unordered = new WeightBasedShippingCalculator([
+        { upToGrams: 2000, costCents: 700 },
+        { upToGrams: 500, costCents: 300 },
+      ]);
+      // 400g should match first bracket (500g) after sort
+      expect(
+        unordered.computeShippingCents([makeLine("a", 400)], 1000),
+      ).toBe(300);
+    });
+
+    it("sums weight across multiple lines with quantity", () => {
+      // 2 * 300g + 1 * 200g = 800g → second bracket (2000g, 700¢)
+      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)];
+      expect(sut.computeShippingCents(lines, 1000)).toBe(700);
+    });
+  });
+});
